package com.performance.varargs;

import java.util.Arrays;
import java.util.List;

public class VarargsUnderTheHood {

    // Compiler translates this to: public static void printAll(String[] names)
    // The method signature in bytecode contains the ACC_VARARGS flag.
    public static void printAll(String... names) {
        for (String name : names) {
            System.out.println(name);
        }
    }

    // Safe generic varargs usage. Requires @SafeVarargs because T... translates to Object[]
    @SafeVarargs
    public static <T> List<T> safeAsList(T... elements) {
        // We must ensure 'elements' never escapes or gets mutated unsafely
        return Arrays.asList(elements);
    }

    public static void main(String[] args) {
        // Under the hood, the compiler rewrites this call to:
        // printAll(new String[] {"Alpha", "Beta", "Gamma"});
        printAll("Alpha", "Beta", "Gamma");

        // Under the hood, this allocates an empty array: printAll(new String[0]);
        printAll();
    }
}
